module tb_TopModule;
    logic [31:0] in;
    logic [31:0] out;

    TopModule uut (
        .in(in),
        .out(out)
    );

    initial begin
        // Test cases
        in = 32'h12345678;
        #10;
        if (out !== 32'h78563412) begin
            $display("SELFTEST FAIL: expected 0x78563412, got 0x%08h", out);
            $finish;
        end

        in = 32'hAABBCCDD;
        #10;
        if (out !== 32'hDDCCBBAA) begin
            $display("SELFTEST FAIL: expected 0xDDCCBBAA, got 0x%08h", out);
            $finish;
        end

        in = 32'h00000001;
        #10;
        if (out !== 32'h01000000) begin
            $display("SELFTEST FAIL: expected 0x01000000, got 0x%08h", out);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
